/* Jungle Chase — standalone pseudo-3D canvas game with embedded character artwork. */
(() => {
  'use strict';
  const modiImage=new Image();
  modiImage.src='data:image/png;base64,';
  const $ = id => document.getElementById(id);
  const canvas = $('canvas'), ctx = canvas.getContext('2d');
  const ui = {overlay:$('overlay'), title:$('title'), message:$('message'), start:$('start'), pause:$('pause'), score:$('score'), best:$('best'), pill:$('pill'), hint:$('hint'), status:$('status')};
  let w=1000,h=550,last=0,mode='ready',distance=0,lane=1,visualLane=1,jumpTime=-1,spawn=1.8,holes=[],caughtTime=0,best=0;
  const jumpDuration=.96, hitZ=.82;
  try { best=Number(localStorage.getItem('monkey-run-best'))||0; } catch (_) { /* Storage may be unavailable when opened locally. */ }
  ui.best.textContent=`${best} m`;
  function resize(){const r=canvas.getBoundingClientRect();w=r.width;h=r.height;const dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);}
  new ResizeObserver(resize).observe(canvas);resize();
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  function perspective(z){return z/(2.5-1.5*z);}
  function project(x,z){const depth=perspective(z);return {x:w/2+x*w*(.025+.48*depth),y:h*.29+h*.76*depth};}
  function polygon(points,color){ctx.fillStyle=color;ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fill();}
  function ellipse(x,y,rx,ry,color){ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(x,y,Math.max(.1,rx),Math.max(.1,ry),0,0,Math.PI*2);ctx.fill();}
  function line(points,color,width){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke();}
  function start(){distance=0;lane=visualLane=1;jumpTime=-1;spawn=1.8;holes=[];caughtTime=0;mode='running';ui.overlay.hidden=true;ui.pause.disabled=false;ui.pause.textContent='Ⅱ';ui.pause.setAttribute('aria-label','Pause game');ui.status.textContent='';}
  function pause(){if(mode==='running'){mode='paused';show('TAKE A BREATHER','The jungle can wait.','Your run is paused. Ready when you are.','Keep running ↗');ui.pause.textContent='▶';ui.pause.setAttribute('aria-label','Resume game');}else if(mode==='paused'){mode='running';ui.overlay.hidden=true;ui.pause.textContent='Ⅱ';ui.pause.setAttribute('aria-label','Pause game');}}
  function show(pill,title,message,button){ui.pill.textContent=pill;ui.title.textContent=title;ui.message.textContent=message;ui.start.textContent=button;ui.hint.textContent='SPACE OR ENTER TO CONTINUE';ui.overlay.hidden=false;ui.start.focus({preventScroll:true});}
  function jump(){if(mode==='running'&&jumpTime<0)jumpTime=0;}
  function move(direction){if(mode==='running')lane=clamp(lane+direction,0,2);}
  function primary(){if(mode==='paused')pause();else if(mode!=='caught')start();}
  ui.start.addEventListener('click',primary);ui.pause.addEventListener('click',pause);
  $('left').addEventListener('pointerdown',e=>{e.preventDefault();move(-1);});$('right').addEventListener('pointerdown',e=>{e.preventDefault();move(1);});$('jump').addEventListener('pointerdown',e=>{e.preventDefault();jump();});
  window.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','Space','KeyA','KeyD','KeyW','KeyP','Escape','Enter'].includes(e.code))return;e.preventDefault();if(e.repeat)return;if(e.code==='KeyP'||e.code==='Escape')pause();else if(e.code==='Space'||e.code==='Enter'){if(mode==='running')jump();else primary();}else if(e.code==='ArrowUp'||e.code==='KeyW')jump();else move(e.code==='ArrowLeft'||e.code==='KeyA'?-1:1);});
  let touch=null;canvas.addEventListener('pointerdown',e=>{touch={x:e.clientX,y:e.clientY};});canvas.addEventListener('pointerup',e=>{if(!touch)return;const dx=e.clientX-touch.x,dy=e.clientY-touch.y;touch=null;if(Math.abs(dx)>25&&Math.abs(dx)>Math.abs(dy))move(Math.sign(dx));else if(dy< -20||Math.abs(dx)<15)jump();});canvas.addEventListener('pointercancel',()=>touch=null);
  document.addEventListener('visibilitychange',()=>{if(document.hidden&&mode==='running')pause();});window.addEventListener('blur',()=>{if(mode==='running')pause();});
  function jumpHeight(){return jumpTime<0?0:Math.sin(Math.PI*jumpTime/jumpDuration);}
  function caught(){mode='caught';caughtTime=0;ui.pause.disabled=true;ui.status.textContent='Missed the jump!';const score=Math.floor(distance);if(score>best){best=score;ui.best.textContent=`${best} m`;try{localStorage.setItem('monkey-run-best',String(best));}catch(_){}}}
  function update(dt){
    if(mode==='caught'){caughtTime+=dt;if(caughtTime>1.05){mode='over';show('CAUGHT THIS TIME','Modi caught up!',`You ran ${Math.floor(distance)} metres. Switch lanes or jump just before a hole reaches your feet.`,'Run again ↗');}return;}
    if(mode!=='running')return;
    distance+=dt*(15+Math.min(distance/120,9));
    visualLane+=(lane-visualLane)*Math.min(1,dt*16);
    if(jumpTime>=0){jumpTime+=dt;if(jumpTime>=jumpDuration)jumpTime=-1;}
    const speed=.23+Math.min(distance/6000,.10);
    spawn-=dt;if(spawn<=0){const chosen=Math.floor(Math.random()*3);holes.push({lane:chosen,z:.02,checked:false});if(distance>230&&Math.random()<.35)holes.push({lane:(chosen+1+Math.floor(Math.random()*2))%3,z:.02,checked:false});spawn=1.65+Math.random()*.45;}
    for(const hole of holes){hole.z+=dt*speed;if(!hole.checked&&hole.z>=hitZ){hole.checked=true;if(Math.abs(visualLane-hole.lane)<.48&&jumpHeight()<.32){caught();break;}}}
    holes=holes.filter(hole=>hole.z<1.16);ui.score.innerHTML=`${Math.floor(distance)} <small>m</small>`;
  }
  function tree(x,y,size,variant){ctx.fillStyle='#586447';ctx.fillRect(x-size*.07,y-size*.6,size*.14,size*.7);ellipse(x,y-size*.8,size*.46,size*.56,variant?'#48694c':'#577b54');ellipse(x-size*.24,y-size*.58,size*.34,size*.37,variant?'#5c8054':'#6c8c5c');ellipse(x+size*.22,y-size*.7,size*.31,size*.4,'#74935e');}
  function person(x,y,s,chaser,t,jumping){
    ctx.save();ctx.translate(x,y);ctx.scale(s,s);
    const stride=Math.sin(t*13),bob=Math.abs(Math.cos(t*13))*3;
    const shadow=ctx.createRadialGradient(0,3,1,0,3,27);
    shadow.addColorStop(0,'#10241f70');shadow.addColorStop(1,'#10241f00');
    ellipse(0,3,chaser?28:22,7,shadow);
    ctx.translate(0,-jumping-bob);ctx.rotate(chaser?stride*.035:(lane-visualLane)*.12+stride*.018);
    if(chaser&&modiImage.complete&&modiImage.naturalWidth){
      const height=112,width=height*modiImage.naturalWidth/modiImage.naturalHeight;
      ctx.drawImage(modiImage,-width/2,-height+4,width,height);
    }else if(chaser){
      // Visible fallback while the embedded image decodes.
      line([{x:-8,y:-25},{x:-12,y:-12},{x:-14+stride*5,y:0}],'#eee6d1',10);
      line([{x:8,y:-25},{x:12,y:-12},{x:14-stride*5,y:0}],'#c9c2b1',10);
      polygon([{x:-15,y:-62},{x:15,y:-62},{x:18,y:-24},{x:-18,y:-24}],'#d98434');
      ellipse(0,-76,15,19,'#c78f67');ellipse(0,-88,16,7,'#eeeae0');ellipse(0,-66,13,12,'#f4f1e7');
      line([{x:-13,y:-79},{x:13,y:-79}],'#8d9590',1.5);
    }else{
      const limb=(points,color,width)=>{line(points,'#203c3840',width+2);line(points,color,width);line(points.map(p=>({x:p.x-2,y:p.y})), '#ffffff20',Math.max(1,width/4));};
      // Alternating bent legs and foreshortened feet, viewed from behind.
      limb([{x:-7,y:-29},{x:-10-stride*3,y:-15},{x:-9-stride*5,y:-2-Math.max(0,stride)*9}],'#294942',10);
      limb([{x:7,y:-29},{x:10+stride*3,y:-15},{x:9+stride*5,y:-2-Math.max(0,-stride)*9}],'#3b6156',10);
      ellipse(-9-stride*5,-1-Math.max(0,stride)*9,7,4,'#e1d7b7');ellipse(9+stride*5,-1-Math.max(0,-stride)*9,7,4,'#f3e7c9');
      limb([{x:-13,y:-53},{x:-21,y:-39+stride*7},{x:-17,y:-30+stride*5}],'#c98a59',7);
      limb([{x:13,y:-53},{x:21,y:-39-stride*7},{x:17,y:-30-stride*5}],'#e1a574',7);
      const shirt=ctx.createLinearGradient(-16,0,16,0);shirt.addColorStop(0,'#9c492c');shirt.addColorStop(.4,'#ec994c');shirt.addColorStop(1,'#b65e31');
      polygon([{x:-14,y:-58},{x:14,y:-58},{x:13,y:-28},{x:-12,y:-28}],shirt);
      line([{x:-9,y:-55},{x:-9,y:-32}],'#604b30',3);line([{x:9,y:-55},{x:9,y:-32}],'#604b30',3);
      const pack=ctx.createLinearGradient(-9,0,10,0);pack.addColorStop(0,'#b78b40');pack.addColorStop(.5,'#e6bd6d');pack.addColorStop(1,'#aa7839');
      ctx.fillStyle=pack;ctx.fillRect(-9,-52,18,21);line([{x:-6,y:-40},{x:6,y:-40}],'#976c36',1.5);
      ellipse(0,-66,10,12,'#ce9463');ellipse(0,-73,13,7,'#243e32');ellipse(-2,-76,11,4,'#527052');line([{x:-15,y:-70},{x:15,y:-70}],'#304f3a',4);
    }ctx.restore();
  }
  function drawHole(hole){
    const z=hole.z,x=hole.lane-1,ring=[];
    for(let i=0;i<18;i++){const a=i/18*Math.PI*2,r=1+.10*Math.sin(i*7.3+hole.lane*2);ring.push(project(x+Math.cos(a)*.34*r,z+Math.sin(a)*.026*r));}
    const center=project(x,z),depth=Math.max(2,h*.042*perspective(z));
    const rim=ring.map(p=>({x:center.x+(p.x-center.x)*1.12,y:center.y+(p.y-center.y)*1.16}));
    polygon(rim,'#72664c');
    ctx.save();ctx.beginPath();ring.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.clip();
    const earth=ctx.createLinearGradient(0,center.y-depth/2,0,center.y+depth);earth.addColorStop(0,'#493b2e');earth.addColorStop(.55,'#241e18');earth.addColorStop(1,'#080e0d');
    ctx.fillStyle=earth;ctx.fillRect(center.x-w,center.y-depth*4,w*2,depth*8);
    for(let i=0;i<ring.length;i++){const a=ring[i],b=ring[(i+1)%ring.length];polygon([a,b,{x:b.x+3,y:b.y+depth},{x:a.x+3,y:a.y+depth}],i%3===0?'#6e5a3e':i%3===1?'#453a2b':'#574731');}
    polygon(ring.map(p=>({x:center.x+(p.x-center.x)*.8,y:p.y+depth*.65})),'#0d1412');ctx.restore();
    for(let i=0;i<ring.length;i++){const a=ring[i],b=ring[(i+1)%ring.length];line([a,b],i<9?'#746345':'#ddd0a1',Math.max(1,3*perspective(z)));if(i%3===0){const out={x:center.x+(a.x-center.x)*1.35,y:center.y+(a.y-center.y)*1.7};line([a,out,{x:out.x+5*perspective(z),y:out.y+depth*.15}],'#655d47',Math.max(.6,1.7*perspective(z)));}}
    for(let i=0;i<5;i++){const p=project(x+Math.sin(i*4.1)*.43,z+.035+(i%2)*.007),size=Math.max(1,5*perspective(z));polygon([{x:p.x-size,y:p.y},{x:p.x,y:p.y-size*.6},{x:p.x+size,y:p.y},{x:p.x+size*.4,y:p.y+size*.45}],'#d2c496');}
  }
  function draw(){
    ctx.save();const cameraBob=mode==='running'?Math.sin(distance*.98)*1.2:0;ctx.translate((visualLane-1)*-3,cameraBob);
    const sky=ctx.createLinearGradient(0,0,0,h);sky.addColorStop(0,'#b9d7c8');sky.addColorStop(.55,'#e5dfaf');sky.addColorStop(1,'#91a25e');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);
    ellipse(w*.72,h*.18,h*.065,h*.065,'#f7ecc3');
    polygon([{x:0,y:h*.36},{x:0,y:h*.25},{x:w*.15,y:h*.11},{x:w*.29,y:h*.28},{x:w*.44,y:h*.12},{x:w*.6,y:h*.31},{x:w*.84,y:h*.14},{x:w,y:h*.25},{x:w,y:h*.45}],'#8daa8c');
    polygon([{x:0,y:h*.4},{x:0,y:h*.28},{x:w*.2,y:h*.23},{x:w*.38,y:h*.36},{x:w*.6,y:h*.22},{x:w*.8,y:h*.32},{x:w,y:h*.24},{x:w,y:h}],'#7b995f');
    for(let i=0;i<22;i++){const side=i%2?-1:1,z=((i/22+distance*.0018)%1);const p=project(side*(1.7+(i%3)*.55),z);tree(p.x,p.y,15+z*z*h*.37,i%3===0);}
    polygon([project(-1.5,0),project(1.5,0),project(1.5,1.2),project(-1.5,1.2)],'#aaa580');
    const road=ctx.createLinearGradient(0,h*.29,0,h);road.addColorStop(0,'#d1c9a1');road.addColorStop(.55,'#b4ac87');road.addColorStop(1,'#938e70');
    polygon([project(-1.44,0),project(1.44,0),project(1.44,1.2),project(-1.44,1.2)],road);
    // Weathered cracks and lane dashes move toward the player with the road.
    for(let i=0;i<27;i++){const z=(i/27+distance*.003)%1.12;const x=((i*7)%19)/7-1.3;const p=project(x,z),q=project(x+.11,z+.024),r=project(x+.04,z+.045);line([p,q,r,project(x+.19,z+.064)],'#837e63',.5+z*1.5);if(i%3===0)line([q,project(x-.08,z+.035)],'#8b8567',1+z);}
    for(const x of [-.5,.5])for(let i=0;i<15;i++){const z=(i/15+distance*.003)%1.1;polygon([project(x-.009,z),project(x+.009,z),project(x+.009,z+.027),project(x-.009,z+.027)],'#e3d8a4');}
    // Continuous border walls, with visible caps and masonry joints.
    for(const side of [-1,1]){const top=(x,z)=>{const p=project(x,z);return{x:p.x,y:p.y-h*(.014+.085*z)};};polygon([project(side*1.52,0),project(side*1.52,1.15),top(side*1.52,1.15),top(side*1.52,0)],'#70715a');polygon([top(side*1.52,0),top(side*1.7,0),top(side*1.7,1.15),top(side*1.52,1.15)],'#d2c99d');for(let i=0;i<19;i++){const z=(i/19+distance*.003)%1.15;line([project(side*1.52,z),top(side*1.52,z)],'#92927a',1+z*2);}}
    for(const hole of [...holes].sort((a,b)=>a.z-b.z))drawHole(hole);
    const t=distance*.075,p=project(visualLane-1,hitZ),scale=clamp(h/480,.65,1.4);let fall=mode==='caught'||mode==='over'?Math.min(caughtTime*35,30):0;
    person(p.x,p.y+fall,scale,false,t,jumpHeight()*h*.19);
    const catchProgress=mode==='caught'||mode==='over'?Math.min(caughtTime*1.8,1):0;
    person(p.x+(1-catchProgress)*w*.085,p.y+h*.13*(1-catchProgress)+12,scale*(1.14-catchProgress*.1),true,t,0);
    const vignette=ctx.createRadialGradient(w/2,h*.4,w*.2,w/2,h*.5,w*.7);vignette.addColorStop(0,'#173d2800');vignette.addColorStop(1,'#173d2835');ctx.fillStyle=vignette;ctx.fillRect(0,0,w,h);ctx.restore();
  }
  // Small simulation steps keep collision checks reliable across display refresh rates.
  function frame(now){let dt=Math.min((now-last)/1000,.06);last=now;while(dt>0){const step=Math.min(dt,1/120);update(step);dt-=step;}draw();requestAnimationFrame(frame);}
  requestAnimationFrame(time=>{last=time;frame(time);});
})();
